package com.operator;

public class Assignment {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int a=5;
		a=a+5;
		System.out.println(a);
		a+=5;
		System.out.println(a);
		a-=5;
		System.out.println(a);
		a*=5;
		System.out.println(a);
		a/=5;
		System.out.println(a);
		a%=5;
		System.out.println(a);

	}

}
//10
//15
//10
//50
//10
//0